INSERT IGNORE INTO `product_reviews` (`id`, `customer_name`, `product_name`, `rating`, `comment`, `created_at`, `admin_reply`) VALUES (1,'Hoàng Minh Đức','MacBook Pro 14-inch M3 Pro',5,'Máy rất mượt, màn hình đẹp tuyệt đối, nhân viên tư vấn nhiệt tình, đóng gói cẩn thận!','2026-10-19 14:23:04','Cảm ơn anh Đức đã luôn tin tưởng và ủng hộ cửa hàng ạ!');
INSERT IGNORE INTO `product_reviews` (`id`, `customer_name`, `product_name`, `rating`, `comment`, `created_at`, `admin_reply`) VALUES (2,'Trần Thị Mai Anh','Dell XPS 13 9340',5,'Thiết kế sang trọng, pin dùng được cả ngày làm việc văn phòng. Rất hài lòng với chính sách bảo hành.','2026-10-17 14:23:04','Shop xin cảm ơn chị Mai Anh, chúc chị có trải nghiệm tuyệt vời cùng máy mới ạ!');
INSERT IGNORE INTO `product_reviews` (`id`, `customer_name`, `product_name`, `rating`, `comment`, `created_at`, `admin_reply`) VALUES (3,'Lê Văn Hùng','ThinkPad X1 Carbon Gen 12',5,'Bàn phím gõ êm nhất trong các dòng laptop từng dùng, máy siêu nhẹ tiện di chuyển công tác.','2026-10-15 14:23:04','Cảm ơn anh Hùng rất nhiều ạ!');
INSERT IGNORE INTO `product_reviews` (`id`, `customer_name`, `product_name`, `rating`, `comment`, `created_at`, `admin_reply`) VALUES (4,'Khách vãng lai (Tuấn)','ASUS ROG Zephyrus G14',4,'Hiệu năng chơi game tốt, tản nhiệt hơi ấm khi chơi game nặng nhưng chấp nhận được. Giao hàng nhanh.','2026-10-13 14:23:04','Dạ cảm ơn bạn, dòng máy mỏng nhẹ cấu hình cao khi chạy full load quạt sẽ tăng tốc tối đa để tản nhiệt ạ.');
INSERT IGNORE INTO `product_reviews` (`id`, `customer_name`, `product_name`, `rating`, `comment`, `created_at`, `admin_reply`) VALUES (5,'Phạm Thu Hà','HP Envy x360 14',5,'Màn hình cảm ứng xoay gập tiện lợi vẽ phác thảo. Cửa hàng hỗ trợ cài đặt phần mềm tận tình.','2026-10-10 14:23:04','Cảm ơn chị Hà đã ủng hộ shop ạ!');
INSERT IGNORE INTO `product_reviews` (`id`, `customer_name`, `product_name`, `rating`, `comment`, `created_at`, `admin_reply`) VALUES (6,'Đỗ Bích Ngọc','Acer Swift Go 14',4,'Màn OLED sắc nét, giá hợp lý trong phân khúc sinh viên và văn phòng.','2026-10-08 14:23:04',NULL);
INSERT IGNORE INTO `product_reviews` (`id`, `customer_name`, `product_name`, `rating`, `comment`, `created_at`, `admin_reply`) VALUES (7,'Khách vãng lai (Minh)','MSI Stealth 16 AI Studio',5,'Máy build rất cứng cáp, chip AI xử lý đồ họa render 3D rất nhanh!','2026-10-05 14:23:04','Shop chúc bạn hoàn thành xuất sắc các dự án thiết kế!');
